#!/usr/bin/env python3
"""Test harness: write md files into a fresh collection dir, run export, print compact summary."""
import json, os, shutil, subprocess, sys, tempfile

EXE = "/workspace/executable"
ROOT = "/tmp/explore/md-parse-cloze/runs"

def run(files, name="t", cmd="export", extra=None, raw=False, keep=False):
    d = os.path.join(ROOT, name)
    shutil.rmtree(d, ignore_errors=True)
    os.makedirs(d)
    for fn, content in files.items():
        p = os.path.join(d, fn)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        if isinstance(content, bytes):
            open(p, "wb").write(content)
        else:
            open(p, "w", encoding="utf-8").write(content)
    args = [EXE, cmd, d] + (extra or [])
    r = subprocess.run(args, capture_output=True)
    out = {"exit": r.returncode,
           "stdout": r.stdout.decode("utf-8", "replace"),
           "stderr": r.stderr.decode("utf-8", "replace"),
           "dir": d}
    return out

def summarize(out, show_text=True):
    print("EXIT=%d" % out["exit"])
    if out["stderr"]:
        print("STDERR: %r" % out["stderr"])
    if out["exit"] != 0 or not out["stdout"].strip():
        if out["stdout"].strip():
            print("STDOUT: %r" % out["stdout"])
        return None
    d = json.loads(out["stdout"])
    for c in d["cards"]:
        loc = c["location"]
        con = c["content"]
        kind = list(con.keys())[0]
        base = "  %s %s L%s-%s fam=%s hash=%s" % (
            os.path.basename(loc["filePath"]), kind, loc["lineStart"], loc["lineEnd"],
            (c["familyHash"] or "None")[:8], c["hash"][:8])
        if kind == "cloze":
            z = con["cloze"]
            t = z["text"]
            seg = t.encode()[z["start"]:z["end"]+1].decode("utf-8", "replace")
            print(base + " start=%d end=%d SEG=%r" % (z["start"], z["end"], seg))
            if show_text:
                print("      text=%r" % t)
        else:
            print(base + " Q=%r A=%r" % (con["basic"]["question"], con["basic"]["answer"]))
    print("  (n=%d)" % len(d["cards"]))
    return d

def go(files, name="t", show_text=True, **kw):
    o = run(files, name, **kw)
    return summarize(o, show_text)

if __name__ == "__main__":
    pass
